import { loadTasks, saveTasks } from "./store";
import { addTask, listTasks, markDone, removeTask } from "./commands";

function usage() {
  return [
    "Usage: todo <subcommand> [args]",
    "Subcommands:",
    "  add <title>       Add a new task",
    "  list              List all tasks",
    "  done <id>         Mark a task as completed",
    "  remove <id>       Remove a task",
  ].join("\n");
}

export function run(argv: string[] = process.argv.slice(2)) {
  const [subcommand, ...rest] = argv;

  switch (subcommand) {
    case "add": {
      const title = rest.join(" ");
      if (!title || !title.trim()) {
        process.stderr.write("Error: task title cannot be empty\n");
        process.exit(1);
      }
      let tasks = loadTasks();
      const result = addTask(tasks, title);
      if (result === null) {
        process.stderr.write("Error: task title cannot be empty\n");
        process.exit(1);
      }
      saveTasks(result);
      break;
    }

    case "list": {
      const tasks = listTasks(loadTasks());
      if (tasks.length === 0) {
        process.stdout.write("No tasks\n");
      } else {
        for (const t of tasks) {
          const marker = t.completed ? "[x]" : "[ ]";
          process.stdout.write(`${marker} ${t.id}: ${t.title}\n`);
        }
      }
      break;
    }

    case "done": {
      if (rest.length === 0) {
        process.stderr.write(usage() + "\n");
        process.exit(1);
      }
      const id = Number(rest[0]);
      if (!Number.isFinite(id)) {
        process.stderr.write("Error: task ID must be a number\n");
        process.exit(1);
      }
      let tasks = loadTasks();
      const result = markDone(tasks, id);
      if (result === null) {
        process.stderr.write("Task not found\n");
        process.exit(1);
      }
      saveTasks(tasks);
      break;
    }

    case "remove": {
      if (rest.length === 0) {
        process.stderr.write(usage() + "\n");
        process.exit(1);
      }
      const id = Number(rest[0]);
      if (!Number.isFinite(id)) {
        process.stderr.write("Error: task ID must be a number\n");
        process.exit(1);
      }
      let tasks = loadTasks();
      const result = removeTask(tasks, id);
      if (result === null) {
        process.stderr.write("Task not found\n");
        process.exit(1);
      }
      saveTasks(result);
      break;
    }

    default: {
      process.stderr.write(usage() + "\n");
      process.exit(1);
    }
  }
}

if (require.main === module) {
  run();
}

